app.json:
{
  "budget": {
    "per_run": 0.05
  },
  "capabilities": {
    "records": {
      "contact": "rw",
      "daily_brief": "rw",
      "meeting": "rw",
      "message": "rw",
      "promise": "rw",
      "sent_mail": "rw",
      "weekly_update": "rw"
    }
  },
  "commands": [
    {
      "id": "mark-message-done",
      "label": "Mark message done",
      "for": "message",
      "run": "mark-message-done",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "mark-message-waiting",
      "label": "Mark message waiting",
      "for": "message",
      "run": "mark-message-waiting",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "return-message-to-triage",
      "label": "Return message to triage",
      "for": "message",
      "run": "return-message-to-triage",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "mark-promise-kept",
      "label": "Mark promise kept",
      "for": "promise",
      "run": "mark-promise-kept",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "mark-promise-dropped",
      "label": "Mark promise dropped",
      "for": "promise",
      "run": "mark-promise-dropped",
      "params": {
        "subject": "$record.id"
      }
    },
    {
      "id": "reopen-promise",
      "label": "Reopen promise",
      "for": "promise",
      "run": "reopen-promise",
      "params": {
        "subject": "$record.id"
      }
    }
  ],
