  "kit": 2,
  "name": "Daily Brief \u0026 Promise Tracker",
  "outputs": {
    "draft-the-weekly-update": {
      "label": "Draft the weekly update",
      "format": "pdf",
      "record": "weekly_update",
      "body": "{{update}}"
