    "prepare-the-daily-brief": {
      "label": "Prepare the daily brief",
      "format": "pdf",
      "record": "daily_brief",
      "body": "{{brief}}"
    }
  },
  "records": {
    "contact": {
      "common": "person",
      "fields": {
        "name": {
          "type": "text"
        }
      },
      "present": {
        "title": "name"
      },
      "title": "name"
    },
    "daily_brief": {
      "fields": {
        "brief": {
          "type": "longtext"
        },
        "title": {
          "type": "text"
        }
      },
      "present": {
        "title": "title"
      },
      "title": "title"
    },
    "meeting": {
      "fields": {
        "attendees": {
          "type": "refs",
          "to": "contact"
        },
        "ends_at": {
          "type": "datetime"
        },
        "location": {
          "type": "text"
        },
        "notes": {
          "type": "longtext"
        },
        "promise_suggestions": {
          "type": "longtext"
        },
        "starts_at": {
          "type": "datetime"
        },
        "title": {
          "type": "text",
          "required": true
        }
      },
      "present": {
        "title": "title",
        "meta": [
          "attendees",
          "ends_at",
          "starts_at"
        ]
      },
      "title": "title"
    },
    "message": {
      "fields": {
        "channel": {
          "type": "enum",
          "values": [
            "Email",
            "Slack"
          ]
        },
        "link": {
          "type": "url"
        },
        "received_at": {
          "type": "datetime"
        },
        "sender": {
          "type": "ref",
          "to": "contact"
        },
        "snippet": {
          "type": "longtext"
        },
        "status": {
          "type": "enum",
          "required": true,
          "default": "Needs me",
          "values": [
            "Needs me",
            "Waiting",
            "Done"
          ]
        },
        "title": {
          "type": "text",
          "required": true
        }
      },
      "present": {
        "title": "title",
        "meta": [
          "received_at"
        ],
        "trailing": "status",
        "state": "status",
        "avatar": "sender",
        "link": "link"
      },
      "title": "title"
    },
    "promise": {
      "fields": {
        "detail": {
          "type": "longtext"
        },
        "due_on": {
          "type": "date"
        },
        "made_on": {
          "type": "date"
        },
        "meeting": {
          "type": "ref",
          "to": "meeting"
        },
        "owed_to": {
          "type": "ref",
          "to": "contact"
        },
        "resolved_on": {
          "type": "date"
        },
        "sent_mail": {
          "type": "ref",
          "to": "sent_mail"
        },
        "source": {
          "type": "enum",
          "values": [
            "Sent mail",
            "Meeting notes"
          ]
        },
        "status": {
          "type": "enum",
          "required": true,
          "default": "Open",
          "values": [
            "Open",
            "Kept",
            "Dropped"
          ]
        },
        "title": {
          "type": "text",
          "required": true
        }
      },
      "present": {
        "title": "title",
        "meta": [
          "due_on",
          "made_on",
          "meeting",
          "resolved_on",
          "sent_mail"
        ],
        "trailing": "status",
        "state": "status",
        "avatar": "owed_to"
      },
      "title": "title"
    },
    "sent_mail": {
      "fields": {
        "body": {
          "type": "longtext"
        },
        "promise_suggestions": {
          "type": "longtext"
        },
        "recipients": {
          "type": "refs",
          "to": "contact"
        },
        "sent_at": {
          "type": "datetime"
        },
        "title": {
          "type": "text"
        }
      },
      "present": {
        "title": "title",
        "meta": [
          "recipients",
          "sent_at"
        ]
      },
      "title": "title"
    },
    "weekly_update": {
      "fields": {
        "title": {
          "type": "text"
        },
        "update": {
          "type": "longtext"
        }
      },
      "present": {
        "title": "title"
      },
      "title": "title"
    }
  },
  "triggers": [
    {
      "id": "suggest-promises-from-meeting-notes",
      "on": "record.changed",
      "type": "meeting",
      "when": "changed(\"title\") || changed(\"starts_at\") || changed(\"attendees\") || changed(\"notes\")",
      "run": "suggest-promises-from-meeting-notes"
    },
    {
      "id": "suggest-promises-from-sent-mail",
      "on": "record.changed",
      "type": "sent_mail",
      "when": "changed(\"title\") || changed(\"recipients\") || changed(\"sent_at\") || changed(\"body\")",
      "run": "suggest-promises-from-sent-mail"
    },
    {
      "id": "prepare-the-daily-brief",
      "on": "schedule",
      "cron": "0 8 * * *",
      "run": "prepare-the-daily-brief"
    },
    {
      "id": "draft-the-weekly-update",
      "on": "schedule",
      "cron": "0 8 * * 1",
      "run": "draft-the-weekly-update"
    }
  ],
  "version": 1
}

