runs/draft-the-weekly-update.yaml:
{
  "run": "draft-the-weekly-update",
  "title": "Draft the weekly update",
  "budget": {
    "per_run": 0.05
  },
  "steps": [
    {
      "id": "draft",
      "ai": {
        "prompt": "Write a concise update for the past week. Cover documented meeting outcomes, commitments made this week, promises kept this week when their resolution date confirms it, and open promises that are overdue or due next week. Note dropped commitments when relevant and flag open questions and blockers supported by the messages or notes. Include owners or recipients and dates where recorded. Do not assume a Kept promise was completed this week if its resolution date is missing, and do not treat unconfirmed suggestions as promises. Save the update as a draft only.\nmeeting.title: {{records(\"meeting\").map(row, row[\"title\"])}}\nmeeting.starts_at: {{records(\"meeting\").map(row, row[\"starts_at\"])}}\nmeeting.notes: {{records(\"meeting\").map(row, row[\"notes\"])}}\nmessage.title: {{records(\"message\").map(row, row[\"title\"])}}\nmessage.received_at: {{records(\"message\").map(row, row[\"received_at\"])}}\nmessage.snippet: {{records(\"message\").map(row, row[\"snippet\"])}}\nmessage.status: {{records(\"message\").map(row, row[\"status\"])}}\npromise.title: {{records(\"promise\").map(row, row[\"title\"])}}\npromise.owed_to: {{records(\"promise\").map(row, row[\"owed_to\"])}}\npromise.made_on: {{records(\"promise\").map(row, row[\"made_on\"])}}\npromise.due_on: {{records(\"promise\").map(row, row[\"due_on\"])}}\npromise.resolved_on: {{records(\"promise\").map(row, row[\"resolved_on\"])}}\npromise.status: {{records(\"promise\").map(row, row[\"status\"])}}\npromise.detail: {{records(\"promise\").map(row, row[\"detail\"])}}",
        "output": {
          "type": "string"
        },
        "example": "Update example 1"
      }
    },
    {
      "id": "save",
      "records.create": {
        "type": "weekly_update",
        "set": {
          "title": "Draft the weekly update",
          "update": "$steps.draft.output"
        }
      }
    },
    {
      "render": {
        "output": "draft-the-weekly-update",
        "record": "{{steps[\"save\"].output.rows[0].id}}",
        "inbox": true
      },
      "id": "inbox"
    }
  ]
}

runs/prepare-the-daily-brief.yaml:
{
  "run": "prepare-the-daily-brief",
  "title": "Prepare the daily brief",
  "budget": {
    "per_run": 0.05
  },
  "steps": [
    {
      "id": "draft",
      "ai": {
        "prompt": "Write a skimmable brief for today. Start with a ranked list of messages marked Needs me and open promises requiring attention. Label email and Slack items, give the next action for each, and include the source message link when available. Rank explicit deadlines, blockers, and overdue commitments ahead of routine follow-ups; do not infer urgency from recency alone. Then show today's meetings in time order with attendees, location when available, and relevant notes. Separate overdue promises, promises due today, and promises due soon; include who is owed and the due date. Flag missing dates rather than guessing.\nmessage.title: {{records(\"message\").map(row, row[\"title\"])}}\nmessage.sender: {{records(\"message\").map(row, row[\"sender\"])}}\nmessage.channel: {{records(\"message\").map(row, row[\"channel\"])}}\nmessage.received_at: {{records(\"message\").map(row, row[\"received_at\"])}}\nmessage.snippet: {{records(\"message\").map(row, row[\"snippet\"])}}\nmessage.link: {{records(\"message\").map(row, row[\"link\"])}}\nmessage.status: {{records(\"message\").map(row, row[\"status\"])}}\nmeeting.title: {{records(\"meeting\").map(row, row[\"title\"])}}\nmeeting.starts_at: {{records(\"meeting\").map(row, row[\"starts_at\"])}}\nmeeting.ends_at: {{records(\"meeting\").map(row, row[\"ends_at\"])}}\nmeeting.attendees: {{records(\"meeting\").map(row, row[\"attendees\"])}}\nmeeting.location: {{records(\"meeting\").map(row, row[\"location\"])}}\nmeeting.notes: {{records(\"meeting\").map(row, row[\"notes\"])}}\npromise.title: {{records(\"promise\").map(row, row[\"title\"])}}\npromise.owed_to: {{records(\"promise\").map(row, row[\"owed_to\"])}}\npromise.due_on: {{records(\"promise\").map(row, row[\"due_on\"])}}\npromise.status: {{records(\"promise\").map(row, row[\"status\"])}}\npromise.detail: {{records(\"promise\").map(row, row[\"detail\"])}}",
        "output": {
          "type": "string"
        },
        "example": "Brief example 1"
      }
    },
    {
      "id": "save",
      "records.create": {
        "type": "daily_brief",
        "set": {
          "brief": "$steps.draft.output",
          "title": "Prepare the daily brief"
        }
      }
    },
    {
      "render": {
        "output": "prepare-the-daily-brief",
        "record": "{{steps[\"save\"].output.rows[0].id}}",
        "inbox": true
      },
      "id": "inbox"
    }
  ]
}

runs/suggest-promises-from-meeting-notes:
{
  "run": "suggest-promises-from-meeting-notes",
  "budget": {
    "per_run": 0.05
  },
  "steps": [
    {
      "id": "derive",
      "ai": {
        "prompt": "Identify commitments the notes explicitly assign to me. Exclude general discussion and actions owned by other attendees. For each, suggest a short title, who is owed in plain text if supported, the meeting date, any stated or unambiguously relative due date, and a short supporting quote. Do not assume an attendee is owed the work. Leave uncertain details unspecified and present the results as suggestions to confirm in the promise tracker.\nmeeting.title: {{record[\"title\"]}}\nmeeting.starts_at: {{record[\"starts_at\"]}}\nmeeting.attendees: {{record[\"attendees\"]}}\nmeeting.notes: {{record[\"notes\"]}}",
        "output": {
          "type": "string"
        },
        "example": "Promise suggestions example 1"
      }
    },
    {
      "id": "save",
      "records.update": {
        "type": "meeting",
        "id": "$record.id",
        "set": {
          "promise_suggestions": "$steps.derive.output"
        }
      }
    }
  ]
}

runs/suggest-promises-from-sent-mail.yam:
{
  "run": "suggest-promises-from-sent-mail",
  "budget": {
    "per_run": 0.05
  },
  "steps": [
    {
      "id": "derive",
      "ai": {
        "prompt": "Identify explicit commitments made by the sender in the current sent email, not requests, tentative plans, or commitments quoted from someone else. For each, suggest a short title, who is owed in plain text if supported, the date made, any stated or unambiguously relative due date, and a short supporting quote. Flag uncertainty and leave unknown due dates unspecified. Return suggestions to confirm in the promise tracker, not confirmed promises.\nsent_mail.title: {{record[\"title\"]}}\nsent_mail.recipients: {{record[\"recipients\"]}}\nsent_mail.sent_at: {{record[\"sent_at\"]}}\nsent_mail.body: {{record[\"body\"]}}",
        "output": {
          "type": "string"
        },
        "example": "Promise suggestions example 1"
      }
    },
    {
      "id": "save",
      "records.update": {
        "type": "sent_mail",
        "id": "$record.id",
        "set": {
          "promise_suggestions": "$steps.derive.output"
        }
      }
    }
  ]
}

